import type { IntegrationEvent, PersonId, PractitionerId } from '@/shared-kernel';

export const SchedulingEvents = {
  AppointmentScheduled: 'scheduling.appointment-scheduled',
  AppointmentCancelled: 'scheduling.appointment-cancelled',
  AppointmentNoShow: 'scheduling.appointment-no-show',
} as const;

export interface AppointmentScheduled extends IntegrationEvent {
  appointmentId: string;
  personId: PersonId;
  practitionerId: PractitionerId;
  startsAt: string;
  endsAt: string;
}

export interface AppointmentCancelled extends IntegrationEvent {
  appointmentId: string;
  personId: PersonId;
  reason: string;
}

export interface AppointmentNoShow extends IntegrationEvent {
  appointmentId: string;
  personId: PersonId;
  startsAt: string;
}
import { BadRequestException, Body, Controller, Get, HttpCode, Param, Post } from '@nestjs/common';
import { AppointmentsService } from '../application/appointments.service';
import type { Appointment } from '../domain/appointment';

interface ScheduleAppointmentBody {
  practitionerId?: string;
  startsAt?: string;
  durationMinutes?: number;
  requester?: { personId?: string; name?: string; phone?: string };
}

@Controller('scheduling/appointments')
export class AppointmentsController {
  constructor(private readonly appointments: AppointmentsService) {}

  @Post()
  async schedule(@Body() body: ScheduleAppointmentBody) {
    const startsAt = new Date(body.startsAt ?? '');
    const requester = body.requester;
    if (!body.practitionerId || Number.isNaN(startsAt.getTime()) || !requester?.personId || !requester.name) {
      throw new BadRequestException('practitionerId, startsAt and requester{personId,name} are required');
    }
    const appointment = await this.appointments.schedule({
      practitionerId: body.practitionerId,
      startsAt,
      durationMinutes: body.durationMinutes,
      requester: { personId: requester.personId, name: requester.name, phone: requester.phone ?? '' },
    });
    return toResponse(appointment);
  }

  @Get(':id')
  async get(@Param('id') id: string) {
    return toResponse(await this.appointments.get(id));
  }

  @Post(':id/cancel')
  @HttpCode(200)
  async cancel(@Param('id') id: string, @Body() body: { reason?: string }) {
    return toResponse(await this.appointments.cancel(id, body.reason ?? 'not informed'));
  }

  @Post(':id/no-show')
  @HttpCode(200)
  async noShow(@Param('id') id: string) {
    return toResponse(await this.appointments.markNoShow(id));
  }
}

function toResponse(appointment: Appointment) {
  const s = appointment.toSnapshot();
  return {
    id: s.id,
    practitionerId: s.practitionerId,
    requester: s.requester,
    startsAt: s.startsAt.toISOString(),
    endsAt: s.endsAt.toISOString(),
    status: s.status,
    cancelReason: s.cancelReason,
  };
}
import { EventEmitter2 } from '@nestjs/event-emitter';
import { AppointmentScheduled, SchedulingEvents } from '@/contracts/scheduling.events';
import { FixedClock } from '@/shared-kernel';
import { Appointment } from '../domain/appointment';
import { AppointmentRepository } from '../domain/appointment.repository';
import { SlotUnavailableError } from '../domain/appointment.errors';
import { AppointmentsService } from './appointments.service';

class InMemoryAppointmentRepository extends AppointmentRepository {
  readonly items = new Map<string, Appointment>();

  async findById(id: string) {
    return this.items.get(id) ?? null;
  }

  async findScheduledOverlapping(practitionerId: string, from: Date, to: Date) {
    return [...this.items.values()].filter(
      (a) => a.practitionerId === practitionerId && a.status === 'SCHEDULED' && a.startsAt < to && from < a.endsAt,
    );
  }

  async save(appointment: Appointment) {
    this.items.set(appointment.id, Appointment.restore(appointment.toSnapshot()));
  }
}

describe('AppointmentsService', () => {
  const clock = new FixedClock(new Date('2026-03-02T09:00:00Z'));
  let repository: InMemoryAppointmentRepository;
  let events: EventEmitter2;
  let service: AppointmentsService;

  beforeEach(() => {
    repository = new InMemoryAppointmentRepository();
    events = new EventEmitter2();
    service = new AppointmentsService(repository, clock, events);
  });

  const command = {
    practitionerId: 'dr-1',
    requester: { personId: 'person-1', name: 'Ana', phone: '' },
    startsAt: new Date('2026-03-02T10:00:00Z'),
  };

  it('persists the appointment and publishes AppointmentScheduled with the published payload', async () => {
    const published: AppointmentScheduled[] = [];
    events.on(SchedulingEvents.AppointmentScheduled, (e: AppointmentScheduled) => published.push(e));

    const appointment = await service.schedule(command);

    expect(repository.items.get(appointment.id)?.status).toBe('SCHEDULED');
    expect(published).toEqual([
      expect.objectContaining({
        appointmentId: appointment.id,
        personId: 'person-1',
        practitionerId: 'dr-1',
        startsAt: '2026-03-02T10:00:00.000Z',
        endsAt: '2026-03-02T10:30:00.000Z',
      }),
    ]);
  });

  it('rejects a double booking against what is already persisted', async () => {
    await service.schedule(command);

    await expect(service.schedule({ ...command, startsAt: new Date('2026-03-02T10:10:00Z') })).rejects.toThrow(
      SlotUnavailableError,
    );
  });
});
import { Injectable, NotFoundException } from '@nestjs/common';
import { EventEmitter2 } from '@nestjs/event-emitter';
import {
  AppointmentCancelled,
  AppointmentNoShow,
  AppointmentScheduled,
  SchedulingEvents,
} from '@/contracts/scheduling.events';
import { Clock, eventEnvelope, newId, PractitionerId } from '@/shared-kernel';
import { Appointment, DEFAULT_DURATION_MINUTES, Requester } from '../domain/appointment';
import { AppointmentRepository } from '../domain/appointment.repository';

export interface ScheduleAppointmentCommand {
  practitionerId: PractitionerId;
  requester: Requester;
  startsAt: Date;
  durationMinutes?: number;
}

@Injectable()
export class AppointmentsService {
  constructor(
    private readonly appointments: AppointmentRepository,
    private readonly clock: Clock,
    private readonly events: EventEmitter2,
  ) {}

  async schedule(command: ScheduleAppointmentCommand): Promise<Appointment> {
    const duration = command.durationMinutes ?? DEFAULT_DURATION_MINUTES;
    const endsAt = new Date(command.startsAt.getTime() + duration * 60_000);
    const agenda = await this.appointments.findScheduledOverlapping(
      command.practitionerId,
      command.startsAt,
      endsAt,
    );
    const appointment = Appointment.schedule(
      { id: newId(), ...command, durationMinutes: duration },
      this.clock.now(),
      agenda,
    );
    await this.appointments.save(appointment);

    const event: AppointmentScheduled = {
      ...eventEnvelope(this.clock.now()),
      appointmentId: appointment.id,
      personId: appointment.requester.personId,
      practitionerId: appointment.practitionerId,
      startsAt: appointment.startsAt.toISOString(),
      endsAt: appointment.endsAt.toISOString(),
    };
    await this.events.emitAsync(SchedulingEvents.AppointmentScheduled, event);
    return appointment;
  }

  async cancel(appointmentId: string, reason: string): Promise<Appointment> {
    const appointment = await this.load(appointmentId);
    appointment.cancel(reason);
    await this.appointments.save(appointment);

    const event: AppointmentCancelled = {
      ...eventEnvelope(this.clock.now()),
      appointmentId: appointment.id,
      personId: appointment.requester.personId,
      reason,
    };
    await this.events.emitAsync(SchedulingEvents.AppointmentCancelled, event);
    return appointment;
  }

  async markNoShow(appointmentId: string): Promise<Appointment> {
    const appointment = await this.load(appointmentId);
    appointment.markNoShow(this.clock.now());
    await this.appointments.save(appointment);

    const event: AppointmentNoShow = {
      ...eventEnvelope(this.clock.now()),
      appointmentId: appointment.id,
      personId: appointment.requester.personId,
      startsAt: appointment.startsAt.toISOString(),
    };
    await this.events.emitAsync(SchedulingEvents.AppointmentNoShow, event);
    return appointment;
  }

  async get(appointmentId: string): Promise<Appointment> {
    return this.load(appointmentId);
  }

  private async load(appointmentId: string): Promise<Appointment> {
    const appointment = await this.appointments.findById(appointmentId);
    if (!appointment) {
      throw new NotFoundException(`Appointment ${appointmentId} not found`);
    }
    return appointment;
  }
}
import type { PersonId, PractitionerId } from '@/shared-kernel';
import {
  AppointmentInPastError,
  InvalidAppointmentTransitionError,
  NoShowBeforeStartError,
  SlotUnavailableError,
} from './appointment.errors';

export type AppointmentStatus = 'SCHEDULED' | 'CANCELLED' | 'NO_SHOW';

export interface Requester {
  personId: PersonId;
  name: string;
  phone: string;
}

export interface AppointmentSnapshot {
  id: string;
  practitionerId: PractitionerId;
  requester: Requester;
  startsAt: Date;
  endsAt: Date;
  status: AppointmentStatus;
  cancelReason: string | null;
}

export interface ScheduleAppointmentInput {
  id: string;
  practitionerId: PractitionerId;
  requester: Requester;
  startsAt: Date;
  durationMinutes?: number;
}

export const DEFAULT_DURATION_MINUTES = 30;

export class Appointment {
  private constructor(private props: AppointmentSnapshot) {}

  static schedule(
    input: ScheduleAppointmentInput,
    now: Date,
    practitionerAgenda: readonly Appointment[],
  ): Appointment {
    if (input.startsAt.getTime() <= now.getTime()) {
      throw new AppointmentInPastError();
    }
    const duration = input.durationMinutes ?? DEFAULT_DURATION_MINUTES;
    const endsAt = new Date(input.startsAt.getTime() + duration * 60_000);
    const candidate = new Appointment({
      id: input.id,
      practitionerId: input.practitionerId,
      requester: input.requester,
      startsAt: input.startsAt,
      endsAt,
      status: 'SCHEDULED',
      cancelReason: null,
    });
    if (practitionerAgenda.some((other) => candidate.conflictsWith(other))) {
      throw new SlotUnavailableError();
    }
    return candidate;
  }

  static restore(snapshot: AppointmentSnapshot): Appointment {
    return new Appointment({ ...snapshot });
  }

  get id(): string {
    return this.props.id;
  }

  get status(): AppointmentStatus {
    return this.props.status;
  }

  get startsAt(): Date {
    return this.props.startsAt;
  }

  get endsAt(): Date {
    return this.props.endsAt;
  }

  get requester(): Requester {
    return this.props.requester;
  }

  get practitionerId(): PractitionerId {
    return this.props.practitionerId;
  }

  cancel(reason: string): void {
    if (this.props.status !== 'SCHEDULED') {
      throw new InvalidAppointmentTransitionError('cancel', this.props.status);
    }
    this.props.status = 'CANCELLED';
    this.props.cancelReason = reason;
  }

  markNoShow(now: Date): void {
    if (this.props.status !== 'SCHEDULED') {
      throw new InvalidAppointmentTransitionError('mark as no-show', this.props.status);
    }
    if (now.getTime() < this.props.startsAt.getTime()) {
      throw new NoShowBeforeStartError();
    }
    this.props.status = 'NO_SHOW';
  }

  conflictsWith(other: Appointment): boolean {
    return (
      other.id !== this.id &&
      other.status === 'SCHEDULED' &&
      other.practitionerId === this.practitionerId &&
      this.startsAt < other.endsAt &&
      other.startsAt < this.endsAt
    );
  }

  toSnapshot(): AppointmentSnapshot {
    return { ...this.props, requester: { ...this.props.requester } };
  }
}
import { DomainError } from '@/shared-kernel';

export class AppointmentInPastError extends DomainError {
  constructor() {
    super('An appointment cannot be scheduled in the past');
  }
}

export class SlotUnavailableError extends DomainError {
  constructor() {
    super('The practitioner already has an appointment in this slot');
  }
}

export class InvalidAppointmentTransitionError extends DomainError {
  constructor(action: string, status: string) {
    super(`Cannot ${action} an appointment that is ${status}`);
  }
}

export class NoShowBeforeStartError extends DomainError {
  constructor() {
    super('A no-show can only be recorded after the appointment start time');
  }
}
